}

// ─── Notification ─────────────────────────────────────────────────────────────

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO timestamp
}

// ─── Event Bus ────────────────────────────────────────────────────────────────

export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
  projectId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  assigneeId: string | null;
  body: string;
}

export type EventPayloadMap = {
  'task.assigned': TaskAssignedPayload;
  'task.status_changed': TaskStatusChangedPayload;
  'comment.added': CommentAddedPayload;
};

export type EventName = keyof EventPayloadMap;

import { EventName, EventPayloadMap } from './types';

type Handler<E extends EventName> = (payload: EventPayloadMap[E]) => void;

/**
 * Simple in-memory publish/subscribe event bus.
 * Services publish named events with typed payloads.
 * Other services subscribe to those events by name.
 */
export class EventBus {
  // Store handlers as a map from event name → array of callbacks.
  // We use `any` here only inside the private map; the public API is fully typed.
  private handlers: Map<EventName, Array<Handler<any>>> = new Map();

  /** Subscribe to an event. Returns an unsubscribe function. */
  subscribe<E extends EventName>(event: E, handler: Handler<E>): () => void {
    if (!this.handlers.has(event)) {
      this.handlers.set(event, []);
    }
    this.handlers.get(event)!.push(handler);

    return () => {
      const list = this.handlers.get(event);
      if (list) {
        const idx = list.indexOf(handler);
        if (idx !== -1) list.splice(idx, 1);
      }
    };
  }

  /** Publish an event, synchronously calling all registered handlers. */
  publish<E extends EventName>(event: E, payload: EventPayloadMap[E]): void {
    const list = this.handlers.get(event);
    if (!list || list.length === 0) return;
    // Iterate over a shallow copy so that unsubscribes inside handlers are safe.
    for (const handler of [...list]) {
      try {
        handler(payload);
      } catch (err) {
        console.error(`[EventBus] Error in handler for "${event}":`, err);
      }
    }
  }
}

import { randomUUID } from 'crypto';
import { User, CreateUserDTO, UpdateUserDTO } from './types';

export class UserService {
  private users: Map<string, User> = new Map();

  /** Create a new user and return it. */
  createUser(dto: CreateUserDTO): User {
    if (!dto.name || dto.name.trim() === '') {
      throw new Error('User name is required.');
    }
    if (!dto.email || dto.email.trim() === '') {
      throw new Error('User email is required.');
    }
    // Enforce unique email
    for (const u of this.users.values()) {
      if (u.email.toLowerCase() === dto.email.toLowerCase()) {
        throw new Error(`Email "${dto.email}" is already in use.`);
      }
    }

    const user: User = {
      id: randomUUID(),
      name: dto.name.trim(),
      email: dto.email.trim().toLowerCase(),
    };
    this.users.set(user.id, user);
    return user;
  }

  /** Return all users. */
  listUsers(): User[] {
    return Array.from(this.users.values());
  }

  /** Return a single user by ID, or undefined if not found. */
  getUserById(id: string): User | undefined {
    return this.users.get(id);
  }

  /** Update an existing user. Throws if not found. */
  updateUser(id: string, dto: UpdateUserDTO): User {
    const user = this.users.get(id);
    if (!user) throw new Error(`User "${id}" not found.`);

    if (dto.email !== undefined) {
      const email = dto.email.trim().toLowerCase();
      for (const u of this.users.values()) {
        if (u.id !== id && u.email === email) {
          throw new Error(`Email "${dto.email}" is already in use.`);
        }
      }
      user.email = email;
    }

    if (dto.name !== undefined) {
      if (dto.name.trim() === '') throw new Error('User name cannot be empty.');
      user.name = dto.name.trim();
    }

    return user;
  }

  /** Delete a user by ID. Throws if not found. */
  deleteUser(id: string): void {
    if (!this.users.has(id)) throw new Error(`User "${id}" not found.`);
    this.users.delete(id);
  }
}

import { randomUUID } from 'crypto';
import { Project, CreateProjectDTO, UpdateProjectDTO } from './types';

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  /** Create a new project and return it. */
  createProject(dto: CreateProjectDTO): Project {
    if (!dto.name || dto.name.trim() === '') {
      throw new Error('Project name is required.');
    }

    const project: Project = {
      id: randomUUID(),
      name: dto.name.trim(),
      description: (dto.description ?? '').trim(),
      memberIds: [],
    };
    this.projects.set(project.id, project);
    return project;
  }

  /** Return all projects. */
  listProjects(): Project[] {
    return Array.from(this.projects.values());
  }

  /** Return a single project by ID, or undefined if not found. */
  getProjectById(id: string): Project | undefined {
    return this.projects.get(id);
  }

  /** Update an existing project. Throws if not found. */
  updateProject(id: string, dto: UpdateProjectDTO): Project {
    const project = this.projects.get(id);
    if (!project) throw new Error(`Project "${id}" not found.`);

    if (dto.name !== undefined) {
      if (dto.name.trim() === '') throw new Error('Project name cannot be empty.');
      project.name = dto.name.trim();
    }
    if (dto.description !== undefined) {
      project.description = dto.description.trim();
    }

    return project;
  }

  /** Delete a project by ID. Throws if not found. */
  deleteProject(id: string): void {
    if (!this.projects.has(id)) throw new Error(`Project "${id}" not found.`);
    this.projects.delete(id);
  }

  /** Add a member (by userId) to a project. Throws if project not found. */
  addMember(projectId: string, userId: string): Project {
    const project = this.projects.get(projectId);
    if (!project) throw new Error(`Project "${projectId}" not found.`);
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  /** Remove a member (by userId) from a project. Throws if project not found. */
  removeMember(projectId: string, userId: string): Project {
    const project = this.projects.get(projectId);
    if (!project) throw new Error(`Project "${projectId}" not found.`);
    project.memberIds = project.memberIds.filter((id) => id !== userId);
    return project;
  }
}

import { randomUUID } from 'crypto';
import { Task, CreateTaskDTO, UpdateTaskDTO, TaskStatus } from './types';
import { EventBus } from './event-bus';

// Ordered list of valid statuses — a task may only move forward.
const STATUS_ORDER: TaskStatus[] = ['todo', 'in-progress', 'done'];

function statusIndex(s: TaskStatus): number {
  return STATUS_ORDER.indexOf(s);
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();

  constructor(private readonly eventBus: EventBus) {}

  /** Create a new task within a project. */
  createTask(dto: CreateTaskDTO): Task {
    if (!dto.title || dto.title.trim() === '') {
      throw new Error('Task title is required.');
    }
    if (!dto.projectId) {
      throw new Error('Task projectId is required.');
    }

    const task: Task = {
      id: randomUUID(),
      title: dto.title.trim(),
      description: (dto.description ?? '').trim(),
      status: 'todo',
      assigneeId: null,
      projectId: dto.projectId,
    };
    this.tasks.set(task.id, task);
    return task;
  }

  /** Return all tasks, optionally filtered by projectId. */
  listTasks(projectId?: string): Task[] {
    const all = Array.from(this.tasks.values());
    return projectId ? all.filter((t) => t.projectId === projectId) : all;
  }

  /** Return a single task by ID, or undefined if not found. */
  getTaskById(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  /** Update task title / description. Throws if not found. */
  updateTask(id: string, dto: UpdateTaskDTO): Task {
    const task = this.tasks.get(id);
    if (!task) throw new Error(`Task "${id}" not found.`);

    if (dto.title !== undefined) {
      if (dto.title.trim() === '') throw new Error('Task title cannot be empty.');
      task.title = dto.title.trim();
    }
    if (dto.description !== undefined) {
      task.description = dto.description.trim();
    }

    return task;
  }

  /** Delete a task by ID. Throws if not found. */
  deleteTask(id: string): void {
    if (!this.tasks.has(id)) throw new Error(`Task "${id}" not found.`);
    this.tasks.delete(id);
  }

  /**
   * Transition a task's status.
   * Valid transitions: todo → in-progress → done
   * Backwards transitions are rejected.
   */
  changeStatus(id: string, newStatus: TaskStatus): Task {
    const task = this.tasks.get(id);
    if (!task) throw new Error(`Task "${id}" not found.`);

    if (!STATUS_ORDER.includes(newStatus)) {
      throw new Error(`Invalid status "${newStatus}".`);
    }

    if (statusIndex(newStatus) <= statusIndex(task.status)) {
      throw new Error(
        `Invalid status transition from "${task.status}" to "${newStatus}". ` +
          `Status may only move forward: todo → in-progress → done.`
      );
    }

    const oldStatus = task.status;
    task.status = newStatus;

    this.eventBus.publish('task.status_changed', {
      taskId: task.id,
      taskTitle: task.title,
      oldStatus,
      newStatus,
      assigneeId: task.assigneeId,
      projectId: task.projectId,
    });

    return task;
  }

  /**
   * Assign a task to a user.
   * Passing null unassigns the task.
   */
  assignTask(id: string, assigneeId: string | null): Task {
    const task = this.tasks.get(id);
    if (!task) throw new Error(`Task "${id}" not found.`);

    task.assigneeId = assigneeId;

    if (assigneeId !== null) {
      this.eventBus.publish('task.assigned', {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId,
        projectId: task.projectId,
      });
    }

    return task;
  }
}

import { randomUUID } from 'crypto';
import { Comment, CreateCommentDTO } from './types';
import { EventBus } from './event-bus';

export class CommentService {
  private comments: Map<string, Comment> = new Map();

  constructor(private readonly eventBus: EventBus) {}

  /**
   * Add a comment to a task.
   * The caller (router) is responsible for supplying the task's current
   * assigneeId so the event payload can carry it for notification purposes.
   */
  createComment(
    dto: CreateCommentDTO,
    taskTitle: string,
    assigneeId: string | null
  ): Comment {
    if (!dto.taskId) throw new Error('Comment taskId is required.');
    if (!dto.authorId) throw new Error('Comment authorId is required.');
    if (!dto.body || dto.body.trim() === '') {
      throw new Error('Comment body is required.');
    }

    const comment: Comment = {
      id: randomUUID(),
      taskId: dto.taskId,
      authorId: dto.authorId,
      body: dto.body.trim(),
      createdAt: new Date().toISOString(),
    };
    this.comments.set(comment.id, comment);

    this.eventBus.publish('comment.added', {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle,
      authorId: comment.authorId,
      assigneeId,
      body: comment.body,
    });

    return comment;
  }

  /** Return all comments, optionally filtered by taskId. */
  listComments(taskId?: string): Comment[] {
    const all = Array.from(this.comments.values());
    return taskId ? all.filter((c) => c.taskId === taskId) : all;
  }

  /** Return a single comment by ID, or undefined if not found. */
  getCommentById(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  /** Delete a comment by ID. Throws if not found. */
  deleteComment(id: string): void {
    if (!this.comments.has(id)) throw new Error(`Comment "${id}" not found.`);
    this.comments.delete(id);
  }
}

import { randomUUID } from 'crypto';
import { Notification, EventPayloadMap } from './types';
import { EventBus } from './event-bus';

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(private readonly eventBus: EventBus) {
    this.registerSubscriptions();
  }

  // ─── Event Subscriptions ──────────────────────────────────────────────────

  private registerSubscriptions(): void {
    // Notify the assignee when a task is assigned to them.
    this.eventBus.subscribe('task.assigned', (payload: EventPayloadMap['task.assigned']) => {
      this.createNotification(
        payload.assigneeId,
        `You have been assigned to task "${payload.taskTitle}".`
      );
    });

    // Notify the assignee when a task's status changes (if there is one).
    this.eventBus.subscribe(
      'task.status_changed',
      (payload: EventPayloadMap['task.status_changed']) => {
        if (payload.assigneeId) {
          this.createNotification(
            payload.assigneeId,
            `Task "${payload.taskTitle}" status changed from "${payload.oldStatus}" to "${payload.newStatus}".`
          );
        }
      }
    );

    // Notify the task's assignee when a new comment is added (but not if the
    // author is the assignee — no self-notification).
    this.eventBus.subscribe('comment.added', (payload: EventPayloadMap['comment.added']) => {
      if (payload.assigneeId && payload.assigneeId !== payload.authorId) {
        this.createNotification(
          payload.assigneeId,
          `New comment on task "${payload.taskTitle}": "${payload.body.substring(0, 80)}${payload.body.length > 80 ? '…' : ''}"`
        );
      }
    });
  }

  // ─── Internal helpers ─────────────────────────────────────────────────────

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notifications.set(notification.id, notification);
    return notification;
  }

  // ─── Public API ───────────────────────────────────────────────────────────

  /** Return all notifications, optionally filtered by userId. */
  listNotifications(userId?: string): Notification[] {
    const all = Array.from(this.notifications.values());
    return userId ? all.filter((n) => n.userId === userId) : all;
  }

  /** Return a single notification by ID, or undefined if not found. */
  getNotificationById(id: string): Notification | undefined {
    return this.notifications.get(id);
  }

  /** Mark a notification as read. Throws if not found. */
  markAsRead(id: string): Notification {
    const notification = this.notifications.get(id);
    if (!notification) throw new Error(`Notification "${id}" not found.`);
    notification.read = true;
    return notification;
  }
}

import { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { UserService } from './user-service';
import { ProjectService } from './project-service';
import { TaskService } from './task-service';
import { CommentService } from './comment-service';
import { NotificationService } from './notification-service';
import { TaskStatus } from './types';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/** Read the entire request body and parse it as JSON. */
function readBody(req: IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', (chunk: Buffer) => { raw += chunk.toString(); });
    req.on('end', () => {
      if (!raw.trim()) {
        resolve({});
        return;
      }
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error('Invalid JSON body.'));
      }
    });
    req.on('error', reject);
  });
}

/** Send a JSON response. */
function sendJSON(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body, null, 2);
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

/** Send a standard error response. */
function sendError(res: ServerResponse, status: number, message: string): void {
  sendJSON(res, status, { error: message });
}

// ─── Router ───────────────────────────────────────────────────────────────────

export class Router {
  constructor(
    private readonly userService: UserService,
    private readonly projectService: ProjectService,
    private readonly taskService: TaskService,
    private readonly commentService: CommentService,
    private readonly notificationService: NotificationService
  ) {}

  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const baseURL = `http://${req.headers.host ?? 'localhost'}`;
    const url = new URL(req.url ?? '/', baseURL);
    const method = req.method?.toUpperCase() ?? 'GET';
    const pathname = url.pathname.replace(/\/$/, '') || '/'; // strip trailing slash

    // Split path into segments, removing empty strings produced by leading slash.
    const segments = pathname.split('/').filter(Boolean);
    // e.g. /users/123  → ['users', '123']
    // e.g. /projects/abc/members → ['projects', 'abc', 'members']

    try {
      // ── Users ─────────────────────────────────────────────────────────────
      if (segments[0] === 'users') {
        await this.handleUsers(method, segments, url, req, res);

      // ── Projects ──────────────────────────────────────────────────────────
      } else if (segments[0] === 'projects') {
        await this.handleProjects(method, segments, url, req, res);

      // ── Tasks ─────────────────────────────────────────────────────────────
      } else if (segments[0] === 'tasks') {
        await this.handleTasks(method, segments, url, req, res);

      // ── Comments ──────────────────────────────────────────────────────────
      } else if (segments[0] === 'comments') {
        await this.handleComments(method, segments, url, req, res);

      // ── Notifications ─────────────────────────────────────────────────────
      } else if (segments[0] === 'notifications') {
        await this.handleNotifications(method, segments, url, req, res);

      } else {
        sendError(res, 404, 'Not found.');
      }
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      // Distinguish "not found" type errors from genuine bad requests.
      if (message.toLowerCase().includes('not found')) {
        sendError(res, 404, message);
      } else {
        sendError(res, 400, message);
      }
    }
  }

  // ── /users ────────────────────────────────────────────────────────────────

  private async handleUsers(
    method: string,
    segments: string[],
    _url: URL,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = segments[1]; // may be undefined

    if (!id) {
      // GET /users
      if (method === 'GET') {
        return sendJSON(res, 200, this.userService.listUsers());
      }
      // POST /users
      if (method === 'POST') {
        const body = await readBody(req) as Record<string, unknown>;
        const user = this.userService.createUser({
          name: String(body.name ?? ''),
          email: String(body.email ?? ''),
        });
        return sendJSON(res, 201, user);
      }
      return sendError(res, 405, 'Method not allowed.');
    }

    // GET /users/:id
    if (method === 'GET') {
      const user = this.userService.getUserById(id);
      if (!user) return sendError(res, 404, `User "${id}" not found.`);
      return sendJSON(res, 200, user);
    }
    // PUT /users/:id
    if (method === 'PUT') {
      const body = await readBody(req) as Record<string, unknown>;
      const user = this.userService.updateUser(id, {
        name: body.name !== undefined ? String(body.name) : undefined,
        email: body.email !== undefined ? String(body.email) : undefined,
      });
      return sendJSON(res, 200, user);
    }
    // DELETE /users/:id
    if (method === 'DELETE') {
      this.userService.deleteUser(id);
      return sendJSON(res, 200, { message: `User "${id}" deleted.` });
    }

    return sendError(res, 405, 'Method not allowed.');
  }

  // ── /projects ─────────────────────────────────────────────────────────────

  private async handleProjects(
    method: string,
    segments: string[],
    _url: URL,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = segments[1];
    const subResource = segments[2]; // e.g. 'members'

    // /projects
    if (!id) {
      if (method === 'GET') {
        return sendJSON(res, 200, this.projectService.listProjects());
      }
      if (method === 'POST') {
        const body = await readBody(req) as Record<string, unknown>;
        const project = this.projectService.createProject({
          name: String(body.name ?? ''),
          description: String(body.description ?? ''),
        });
        return sendJSON(res, 201, project);
      }
      return sendError(res, 405, 'Method not allowed.');
    }

    // /projects/:id/members
    if (subResource === 'members') {
      if (method === 'POST') {
        const body = await readBody(req) as Record<string, unknown>;
        const userId = String(body.userId ?? '');
        if (!userId) return sendError(res, 400, 'userId is required.');
        // Verify the user exists (cross-service lookup via the router)
        const user = this.userService.getUserById(userId);
        if (!user) return sendError(res, 404, `User "${userId}" not found.`);
        const project = this.projectService.addMember(id, userId);
        return sendJSON(res, 200, project);
      }
      if (method === 'DELETE') {
        const body = await readBody(req) as Record<string, unknown>;
        const userId = String(body.userId ?? '');
        if (!userId) return sendError(res, 400, 'userId is required.');
        const project = this.projectService.removeMember(id, userId);
        return sendJSON(res, 200, project);
      }
      return sendError(res, 405, 'Method not allowed.');
    }

    // /projects/:id
    if (method === 'GET') {
      const project = this.projectService.getProjectById(id);
      if (!project) return sendError(res, 404, `Project "${id}" not found.`);
      return sendJSON(res, 200, project);
    }
    if (method === 'PUT') {
      const body = await readBody(req) as Record<string, unknown>;
      const project = this.projectService.updateProject(id, {
        name: body.name !== undefined ? String(body.name) : undefined,
        description: body.description !== undefined ? String(body.description) : undefined,
      });
      return sendJSON(res, 200, project);
    }
    if (method === 'DELETE') {
      this.projectService.deleteProject(id);
      return sendJSON(res, 200, { message: `Project "${id}" deleted.` });
    }

    return sendError(res, 405, 'Method not allowed.');
  }

  // ── /tasks ────────────────────────────────────────────────────────────────

  private async handleTasks(
    method: string,
    segments: string[],
    url: URL,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = segments[1];
    const subResource = segments[2]; // 'status' | 'assign'

    // /tasks[?projectId=...]
    if (!id) {
      if (method === 'GET') {
        const projectId = url.searchParams.get('projectId') ?? undefined;
        return sendJSON(res, 200, this.taskService.listTasks(projectId));
      }
      if (method === 'POST') {
        const body = await readBody(req) as Record<string, unknown>;
        // Validate that the referenced project exists (cross-service, via router)
        const projectId = String(body.projectId ?? '');
        if (!projectId) return sendError(res, 400, 'projectId is required.');
        const project = this.projectService.getProjectById(projectId);
        if (!project) return sendError(res, 404, `Project "${projectId}" not found.`);

        const task = this.taskService.createTask({
          title: String(body.title ?? ''),
          description: String(body.description ?? ''),
          projectId,
        });
        return sendJSON(res, 201, task);
      }
      return sendError(res, 405, 'Method not allowed.');
    }

    // /tasks/:id/status
    if (subResource === 'status') {
      if (method === 'PUT') {
        const body = await readBody(req) as Record<string, unknown>;
        const newStatus = String(body.status ?? '') as TaskStatus;
        const task = this.taskService.changeStatus(id, newStatus);
        return sendJSON(res, 200, task);
      }
      return sendError(res, 405, 'Method not allowed.');
    }

    // /tasks/:id/assign
    if (subResource === 'assign') {
      if (method === 'PUT') {
        const body = await readBody(req) as Record<string, unknown>;
        const assigneeId = body.assigneeId === null ? null : String(body.assigneeId ?? '');

        // Validate assignee if provided
        if (assigneeId !== null && assigneeId !== '') {
          const user = this.userService.getUserById(assigneeId);
          if (!user) return sendError(res, 404, `User "${assigneeId}" not found.`);
        }
        const resolvedAssignee = assigneeId === '' ? null : assigneeId;
        const task = this.taskService.assignTask(id, resolvedAssignee);
        return sendJSON(res, 200, task);
      }
      return sendError(res, 405, 'Method not allowed.');
    }

    // /tasks/:id
    if (method === 'GET') {
      const task = this.taskService.getTaskById(id);
      if (!task) return sendError(res, 404, `Task "${id}" not found.`);
      return sendJSON(res, 200, task);
    }
    if (method === 'PUT') {
      const body = await readBody(req) as Record<string, unknown>;
      const task = this.taskService.updateTask(id, {
        title: body.title !== undefined ? String(body.title) : undefined,
        description: body.description !== undefined ? String(body.description) : undefined,
      });
      return sendJSON(res, 200, task);
    }
    if (method === 'DELETE') {
      this.taskService.deleteTask(id);
      return sendJSON(res, 200, { message: `Task "${id}" deleted.` });
    }

    return sendError(res, 405, 'Method not allowed.');
  }

  // ── /comments ─────────────────────────────────────────────────────────────

  private async handleComments(
    method: string,
    segments: string[],
    url: URL,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = segments[1];

    // /comments[?taskId=...]
    if (!id) {
      if (method === 'GET') {
        const taskId = url.searchParams.get('taskId') ?? undefined;
        return sendJSON(res, 200, this.commentService.listComments(taskId));
      }
      if (method === 'POST') {
        const body = await readBody(req) as Record<string, unknown>;

        const taskId = String(body.taskId ?? '');
        const authorId = String(body.authorId ?? '');

        // Cross-service validations via the router
        const task = this.taskService.getTaskById(taskId);
        if (!task) return sendError(res, 404, `Task "${taskId}" not found.`);

        const author = this.userService.getUserById(authorId);
        if (!author) return sendError(res, 404, `User (author) "${authorId}" not found.`);

        const comment = this.commentService.createComment(
          {
            taskId,
            authorId,
            body: String(body.body ?? ''),
          },
          task.title,
          task.assigneeId
        );
        return sendJSON(res, 201, comment);
      }
      return sendError(res, 405, 'Method not allowed.');
    }

    // /comments/:id
    if (method === 'GET') {
      const comment = this.commentService.getCommentById(id);
      if (!comment) return sendError(res, 404, `Comment "${id}" not found.`);
      return sendJSON(res, 200, comment);
    }
    if (method === 'DELETE') {
      this.commentService.deleteComment(id);
      return sendJSON(res, 200, { message: `Comment "${id}" deleted.` });
    }

    return sendError(res, 405, 'Method not allowed.');
  }

  // ── /notifications ────────────────────────────────────────────────────────

  private async handleNotifications(
    method: string,
    segments: string[],
    url: URL,
    _req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = segments[1];
    const subResource = segments[2]; // 'read'

    // /notifications[?userId=...]
    if (!id) {
      if (method === 'GET') {
        const userId = url.searchParams.get('userId') ?? undefined;
        return sendJSON(res, 200, this.notificationService.listNotifications(userId));
      }
      return sendError(res, 405, 'Method not allowed.');
    }

    // /notifications/:id/read
    if (subResource === 'read') {
      if (method === 'PUT') {
        const notification = this.notificationService.markAsRead(id);
        return sendJSON(res, 200, notification);
      }
      return sendError(res, 405, 'Method not allowed.');
    }

    // /notifications/:id
    if (method === 'GET') {
      const notification = this.notificationService.getNotificationById(id);
      if (!notification) return sendError(res, 404, `Notification "${id}" not found.`);
      return sendJSON(res, 200, notification);
    }

    return sendError(res, 405, 'Method not allowed.');
  }
}

